export const SUPPORTED_LANGS = ['tr', 'en'];

export function normalizeLang(lang) {
  return lang === 'en' ? 'en' : 'tr';
}

export function pickLang(value, lang = 'tr') {
  const l = normalizeLang(lang);
  if (value && typeof value === 'object' && !Array.isArray(value) && ('tr' in value || 'en' in value)) {
    return value[l] ?? value.tr ?? value.en;
  }
  return value;
}

export function deepLocalize(value, lang = 'tr') {
  const l = normalizeLang(lang);
  if (!value || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(item => deepLocalize(item, l));
  if ('tr' in value || 'en' in value) {
    const picked = value[l] ?? value.tr ?? value.en;
    return deepLocalize(picked, l);
  }
  const out = {};
  for (const [k, v] of Object.entries(value)) {
    out[k] = deepLocalize(v, l);
  }
  return out;
}

export function ui(lang, key, ...args) {
  const l = normalizeLang(lang);
  const dict = UI_STRINGS[l] || UI_STRINGS.tr;
  const entry = dict[key] ?? UI_STRINGS.tr[key];
  return typeof entry === 'function' ? entry(...args) : entry;
}

